+  @Override
+  @SuppressWarnings("deprecation")
+  public boolean rename(Path src, Path dst) throws IOException {
+    if (fs.isDirectory(src)) {
+      return fs.rename(src, dst);
+    } else {
+      if (fs.isDirectory(dst)) {
+        dst = new Path(dst, src.getName());
