+  @Retries.OnceTranslated
+  private synchronized void reopen(String reason, long targetPos, long length,
+          boolean forceAbort) throws IOException {
+
+    if (isObjectStreamOpen()) {
+      closeStream("reopen(" + reason + ")", forceAbort, false);
+    }
